        /// <summary>The bindings AnimationUtility.GetAnimatableBindings offers for an engine component of each type,
        /// in the Editor's order, without the material property bindings of the renderers that have them
        /// (measured: tests/projects/animbindings, Unity 6000.0.71f1): float bindings, object reference
        /// bindings, and whether material property bindings come first.</summary>
        /// <summary>Whether the Editor offers a float binding of the property for an engine component of
        /// the type: null when the type is not measured.</summary>
        internal static bool? OffersEngineFloat(System.Type type, string propertyName)
        {
            if (type.FullName == null || !s_EngineBindings.TryGetValue(type.FullName, out var engine)) return null;
            return System.Array.IndexOf(engine.Floats, propertyName) >= 0;
        }

